"""Write Qiskit-authored QASM fixtures + Aer reference amplitudes.

    python make_qasm_fixtures.py tests/beta_tests/quantum/fixtures/qasm

Each circuit is built with Qiskit's API (not CJC), exported with
qiskit.qasm2.dumps, and simulated with Aer (statevector, double precision).
The Rust test `qasm_fixtures_match_qiskit_aer` imports the QASM text with
q_from_qasm and compares amplitudes. This checks the importer against another
toolchain's output without needing Python in CI.
"""
import os
import sys

import numpy as np
import qiskit
import qiskit_aer
from qiskit import QuantumCircuit, QuantumRegister, qasm2
from qiskit_aer import AerSimulator

out = sys.argv[1]
os.makedirs(out, exist_ok=True)
rng = np.random.default_rng(20260925)


def bell():
    qc = QuantumCircuit(2)
    qc.h(0)
    qc.cx(0, 1)
    return qc


def every_gate():
    qc = QuantumCircuit(4)
    for q in range(4):
        qc.h(q)
    qc.x(0); qc.y(1); qc.z(2); qc.s(3); qc.t(0)
    qc.rx(0.37, 1); qc.ry(-1.2, 2); qc.rz(np.pi / 3, 3)
    qc.cx(0, 1); qc.cz(1, 2); qc.swap(2, 3); qc.ccx(0, 1, 2)
    qc.barrier()
    qc.rz(2 * np.pi / 7, 0)
    return qc


def two_registers():
    a, b = QuantumRegister(2, "a"), QuantumRegister(3, "b")
    qc = QuantumCircuit(a, b)
    qc.h(a)          # broadcast in QASM
    qc.cx(a[0], b[2])
    qc.ry(0.25, b)
    qc.ccx(a[1], b[0], b[1])
    return qc


def random_circuit(n, depth):
    qc = QuantumCircuit(n)
    for _ in range(depth):
        for q in range(n):
            g = rng.integers(6)
            th = float(rng.uniform(0, 2 * np.pi))
            [qc.h, qc.s, qc.t][g](q) if g < 3 else [qc.rx, qc.ry, qc.rz][g - 3](th, q)
        perm = rng.permutation(n)
        for i in range(0, n - 1, 2):
            qc.cx(int(perm[i]), int(perm[i + 1]))
    return qc


cases = {"bell": bell(), "every_gate": every_gate(), "two_registers": two_registers(),
         "random_8q_d6": random_circuit(8, 6)}
sim = AerSimulator(method="statevector", precision="double")
for name, qc in cases.items():
    text = qasm2.dumps(qc)
    with open(os.path.join(out, name + ".qasm"), "w", encoding="utf-8") as f:
        f.write(text)
    c = qc.copy()
    c.save_statevector()
    sv = np.asarray(sim.run(c).result().get_statevector(c))
    sv.astype("<c16").tofile(os.path.join(out, name + ".aer_c128le.bin"))
with open(os.path.join(out, "README.md"), "w", encoding="utf-8") as f:
    f.write(f"Generated by bench/quantum_compare/externals/make_qasm_fixtures.py with "
            f"qiskit {qiskit.__version__} and qiskit-aer {qiskit_aer.__version__}.\n"
            f"`*.qasm` is qiskit.qasm2.dumps output; `*.aer_c128le.bin` is Aer's statevector "
            f"(little-endian complex128, qubit 0 = least significant bit).\n")
print("wrote", sorted(os.listdir(out)))
